epcionReglas</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_M4_EjecucionHitos</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_M5_CorreoJourney</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Event_Traspaso_Servicios</bpmn:flowNodeRef>\n      </bpmn:lane>\n      <bpmn:lane id=\"Lane_Macro_Servicios\" name=\"ÁREA: SERVICIOS / SOPORTE (Yessenia)\">\n        <bpmn:flowNodeRef>Task_M6_AsignarGestor</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_M7_OperacionTickets</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>End_Macro_Contrato</bpmn:flowNodeRef>\n      </bpmn:lane>\n    </bpmn:laneSet>\n    <bpmn:startEvent id=\"Start_Macro\" name=\"Identificación de Oportunidad\" />\n    <bpmn:sequenceFlow id=\"F_M1\" sourceRef=\"Start_Macro\" targetRef=\"Task_M1_Oportunidad\" />\n    <bpmn:userTask id=\"Task_M1_Oportunidad\" name=\"Crear Pre-Cliente / Pre-Contrato\" />\n    <bpmn:sequenceFlow id=\"F_M2\" sourceRef=\"Task_M1_Oportunidad\" targetRef=\"Task_M2_ReglasCostos\" />\n    <bpmn:serviceTask id=\"Task_M2_ReglasCostos\" name=\"Carga de Reglas de Negocio e Hitos Contractuales\" />\n    <bpmn:sequenceFlow id=\"F_M3\" sourceRef=\"Task_M2_ReglasCostos\" targetRef=\"Event_Cierre_Preventa\" />\n    <bpmn:intermediateThrowEvent id=\"Event_Cierre_Preventa\" name=\"Cierre de Ciclo de Preventa (Paso Responsabilidad)\">\n      <bpmn:messageEventDefinition id=\"Msg_1\" />\n    </bpmn:intermediateThrowEvent>\n    <bpmn:sequenceFlow id=\"F_M4\" sourceRef=\"Event_Cierre_Preventa\" targetRef=\"Task_M3_RecepcionReglas\" />\n    <bpmn:userTask id=\"Task_M3_RecepcionReglas\" name=\"Recepción de Reglas y Asignación Técnico\" />\n    <bpmn:sequenceFlow id=\"F_M5\" sourceRef=\"Task_M3_RecepcionReglas\" targetRef=\"Task_M4_EjecucionHitos\" />\n    <bpmn:userTask id=\"Task_M4_EjecucionHitos\" name=\"Ejecución de Hitos de Implementación\" />\n    <bpmn:sequenceFlow id=\"F_M6\" sourceRef=\"Task_M4_EjecucionHitos\" targetRef=\"Task_M5_CorreoJourney\" />\n    <bpmn:serviceTask id=\"Task_M5_CorreoJo