:flowNodeRef>\n      </bpmn:lane>\n      <bpmn:lane id=\"Lane_Tecnico_Especialista\" name=\"OPERACIÓN: ESPECIALISTA OPERATIVO (N1, N2, N3)\">\n        <bpmn:flowNodeRef>Task_T2_Play</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Gate_Requiere_Apoyo</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_T3_TareaHija</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_T3B_SoporteHija</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_T4_ServicioPrincipal</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_T4B_Stop</bpmn:flowNodeRef>\n      </bpmn:lane>\n    </bpmn:laneSet>\n    <bpmn:startEvent id=\"Start_Ticket\" name=\"Apertura del Ticket en Aranda/NOVAIOPS\" />\n    <bpmn:sequenceFlow id=\"F_T1\" sourceRef=\"Start_Ticket\" targetRef=\"Task_T1_Apertura\" />\n    <bpmn:serviceTask id=\"Task_T1_Apertura\" name=\"Asignación Automática de Ticket a Especialista\" />\n    <bpmn:sequenceFlow id=\"F_T2\" sourceRef=\"Task_T1_Apertura\" targetRef=\"Task_T2_Play\" />\n    <bpmn:userTask id=\"Task_T2_Play\" name=\"Especialista Acciona Botón PLAY (Inicia Conteo)\" />\n    <bpmn:sequenceFlow id=\"F_T3\" sourceRef=\"Task_T2_Play\" targetRef=\"Gate_Requiere_Apoyo\" />\n    <bpmn:exclusiveGateway id=\"Gate_Requiere_Apoyo\" name=\"¿Requiere Apoyo Administrativo?\" />\n    <bpmn:sequenceFlow id=\"F_Hija_Si\" name=\"SÍ\" sourceRef=\"Gate_Requiere_Apoyo\" targetRef=\"Task_T3_TareaHija\" />\n    <bpmn:sequenceFlow id=\"F_Hija_No\" name=\"NO\" sourceRef=\"Gate_Requiere_Apoyo\" targetRef=\"Task_T4_ServicioPrincipal\" />\n    <bpmn:userTask id=\"Task_T3_TareaHija\" name=\"Crear Tarea Hija Ligada al Ticket Padre\" />\n    <bpmn:sequenceFlow id=\"F_Hija_1\" sourceRef=\"Task_T3_TareaHija\" targetRef=\"Task_T3B_SoporteHija\" />\n    <bpmn:userTask id=\"Task_T3B_SoporteHija\" name=\"Ejecutar Documentación o Gestión Proveedor\" />\n    <bpmn:sequenceFlow id=\"F_Hija_2\" sourceRef=\"Task_T3B_SoporteHija\" targetRef=\"Task_T4B_Stop\" />\n    <bpmn:userTask id=\"Task_T4_ServicioPrincipal\" name=\"Ejecutar Resolución de Incidencia Técnica\" />\n    <bpmn:sequenceFlow id=\"F_Padre_1\" sourceRef=\"Task_T4_ServicioPrincipal\" targetRef=\"Task_T4B_Stop\" />\n    <bpmn:userTask id=\"Task_T4B_Stop\" name=\"Especialista Acciona Botón STOP / FINALIZAR\" />\n    <bpmn:sequenceFlow id=\"F_T4\" sourceRef=\"Task_T4B_Stop\" targetRef=\"Task_T5_ReglasNegocio\" />\n    <bpmn:businessRuleTask id=\"Task_T5_ReglasNegocio\" name=\"Aplicar Reglas: Factor Nocturno/Feriado, Excluir Tareas Hijas y Redondeo Mínimo\" />\n    <bpmn:sequenceFlow id=\"F_T5\" sourceRef=\"Task_T5_ReglasNegocio\" targetRef=\"Task_T6_DescuentoBolsa\" />\n    <bpmn:serviceTask id=\"Task_T6_DescuentoBolsa\" name=\"Descuento Automático Horas de Bolsa de Soporte\" />\n    <bpmn:sequenceFlow id=\"F_T6\" sourceRef=\"Task_T6_DescuentoBolsa\" targetRef=\"Task_T7_HojaServicio\" />\n    <bpmn:serviceTask id=\"Task_T7_HojaServicio\" name=\"Generación y Envío de Hoja de Servicio por Correo\" />\n    <bpmn:sequenceFlow id=\"F_T7\" sourceRef=\"Task_T7_HojaServicio\" targetRef=\"Task_T8_ConsolidarTiempo\" />\n    <bpmn:serviceTask id=\"Task_T8_ConsolidarTiempo\" name=\"Consolidar Tiempos y Cargar en Perfil Diario Técnico\" />\n    <bpmn:sequenceFlow id=\"F_T8\" sourceRef=\"Task_T8_ConsolidarTiempo\" targetRef=\"End_Validation\" />\n    <bpmn:endEvent id=\"End_Validation\" name=\"Validación del Sistema: Mínimo 1 Tarea Diaria Registrada\" customFill=\"#EBF7EE\" customStroke=\"#28a745\" />\n  </bpmn:process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_Sonda_Auto\">\n    <bpmndi:BPMNPlane id=\"BPMNPlane_Sonda_Auto\" bpmnElement=\"Collaboration_Control_Tickets\">\n      <bpmndi:BPMNShape id=\"Lane_Tecnico_Especialista_di\" bpmnElement=\"Lane_Tecnico_Especialista\" isHorizontal=\"true\">\n        <dc:Bounds x=\"150\" y=\"260\" width=\"1422\" height=\"160\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Lane_Sistema_NOVAIOPS_di\" bpmnElement=\"Lane_Sistema_NOVAIOPS\" isHorizontal=\"true\">\n        <dc:Bounds x=\"150\" y=\"100\"