INSERT INTO `bpmn_diagrams` VALUES (1,'FLUJO 2: Journey Experience','','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<bpmn:definitions xmlns:bpmn=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\" xmlns:dc=\"http://www.omg.org/spec/DD/20100524/DC\" xmlns:di=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:bioc=\"http://bpmn.io/schema/bpmn/biocolor/1.0\" xmlns:color=\"http://www.omg.org/spec/BPMN/non-normative/color/1.0\" id=\"Definitions_Journey_Sonda\" targetNamespace=\"http://bpmn.io/schema/bpmn\" exporter=\"Camunda Modeler\" exporterVersion=\"5.0.0\">\n  <bpmn:collaboration id=\"Collaboration_Journey_Sonda\">\n    <bpmn:participant id=\"Participant_Sonda\" name=\"SONDA - JOURNEY EXPERIENCE MASTER\" processRef=\"Process_Journey_Cliente\" customStroke=\"#ff5c05\" />\n  </bpmn:collaboration>\n  <bpmn:process id=\"Process_Journey_Cliente\" isExecutable=\"true\">\n    <bpmn:laneSet id=\"LaneSet_Sonda_Edificio\">\n      <bpmn:lane id=\"Lane_Preventa\" name=\"DEPARTAMENTO DE PREVENTA\" customStroke=\"#ff5c05\">\n        <bpmn:flowNodeRef>StartEvent_Oportunidad</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_11_CrearPreCliente</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Gateway_12_NotaPreventaOk</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_14_FeedbackPreventa</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err1B_AjustarPropuesta</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err1_PlanMejoraPreventa</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Event_HandoverComercial</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_12_EnviarPropuesta</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Gateway_11_PropuestaAceptada</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>EndEvent_OportunidadPerdida</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_13_EncuestaPreventa</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Activity_1qlpm0o</bpmn:flowNodeRef>\n      </bpmn:lane>\n      <bpmn:lane id=\"Lane_Ventas\" name=\"DEPARTAMENTO DE VENTAS\" customStroke=\"#28a745\">\n        <bpmn:flowNodeRef>Task_21_AsignarID</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_22_CargarCatalogo</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_23_FirmaContrato</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_24_EncuestaComercial</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Gateway_21_NotaComercialOk</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err2_PlanMejoraComercial</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err2B_RevisarAcuerdos</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err2C_AprobacionRuta</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_25_FeedbackComercial</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Event_HandoverTecnico</bpmn:flowNodeRef>\n      </bpmn:lane>\n      <bpmn:lane id=\"Lane_Implementacion\" name=\"DEPARTAMENTO DE IMPLEMENTACIÓN (Carlos Moreno)\" customStroke=\"#002a54\">\n        <bpmn:flowNodeRef>Task_31_InyectarBolsa</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_32_EjecucionEspecialistas</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_33_CierreTecnico</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_34_EncuestaProyecto</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Gateway_31_NotaProyectoOk</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err3_PlanMejoraProyecto</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err3B_AuditoriaGarantia</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_35_FeedbackTecnico</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Event_HandoverOperativo</bpmn:flowNodeRef>\n      </bpmn:lane>\n      <bpmn:lane id=\"Lane_Soporte\" name=\"DEPARTAMENTO DE SERVICIOS / SOPORTE (Yessenia)\">\n        <bpmn:flowNodeRef>Task_41_ActivacionMesa</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_42_VentanaTiempo</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Gateway_41_NotaSoporteOk</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err4_PlanMejoraInterno</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_Err4B_RegistrarConstancia