--
-- Table structure for table `ci_instances`
--

DROP TABLE IF EXISTS `ci_instances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ci_instances` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_id` int(11) NOT NULL,
  `hostname` varchar(255) NOT NULL,
  `ip_address` varchar(50) DEFAULT NULL,
  `source` enum('manual','zabbix') DEFAULT 'manual',
  `zabbix_host_id` varchar(100) DEFAULT NULL,
  `attributes_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`attributes_json`)),
  `status` enum('Planificación','Activo','Mantenimiento','Retirado') DEFAULT 'Activo',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `description` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `parent_ci_id` int(11) DEFAULT NULL,
  `ci_unique` varchar(20) DEFAULT NULL COMMENT 'SND-0000000000 sequential identifier',
  `sigla` varchar(50) DEFAULT NULL COMMENT 'Etiqueta / Sigla del CI',
  PRIMARY KEY (`id`),
  UNIQUE KEY `ci_unique` (`ci_unique`),
  KEY `category_id` (`category_id`),
  KEY `fk_parent_ci` (`parent_ci_id`),
  CONSTRAINT `ci_instances_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `ci_categories` (`id`),
  CONSTRAINT `fk_parent_ci` FOREIGN KEY (`parent_ci_id`) REFERENCES `ci_instances` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=305 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

