DROP TABLE IF EXISTS `dc_racks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `dc_racks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `room_id` int(11) DEFAULT NULL,
  `client` varchar(100) NOT NULL DEFAULT 'VILASECA',
  `city` varchar(100) NOT NULL DEFAULT '',
  `location` varchar(255) NOT NULL DEFAULT '',
  `name` varchar(255) NOT NULL,
  `total_u` int(11) DEFAULT 42,
  `grid_x` int(11) DEFAULT 0,
  `grid_y` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `width_tiles` int(11) DEFAULT 1,
  `depth_tiles` int(11) DEFAULT 2,
  `rotation` int(11) NOT NULL DEFAULT 0,
  `numbering_dir` enum('UP','DOWN') NOT NULL DEFAULT 'DOWN',
  `description` text DEFAULT NULL,
  `photos_json` text DEFAULT NULL,
  `observations_json` text DEFAULT NULL,
  `z_index` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `dc_racks_ibfk_1` (`room_id`),
  CONSTRAINT `dc_racks_ibfk_1` FOREIGN KEY (`room_id`) REFERENCES `dc_rooms` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
