CREATE TABLE `host_interfaces` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `hostid` varchar(50) NOT NULL,
  `interface_index` varchar(100) NOT NULL,
  `interface_name` varchar(255) DEFAULT NULL,
  `interface_type` varchar(50) DEFAULT NULL,
  `alias` text DEFAULT NULL,
  `vlan` varchar(50) DEFAULT NULL,
  `status` varchar(20) DEFAULT NULL,
  `bits_received` bigint(20) DEFAULT 0,
  `bits_sent` bigint(20) DEFAULT 0,
  `connected_hostid` varchar(50) DEFAULT NULL,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_host_ifindex` (`hostid`,`interface_index`)
) ENGINE=InnoDB AUTO_INCREMENT=2232 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
