CREATE TABLE `manual_portmap_surveys` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `client` varchar(255) NOT NULL,
  `location` varchar(255) NOT NULL,
  `area` varchar(255) DEFAULT NULL,
  `device_name` varchar(255) NOT NULL,
  `device_label` varchar(255) DEFAULT NULL,
  `device_type` varchar(100) DEFAULT NULL,
  `vendor` varchar(100) DEFAULT NULL,
  `model` varchar(255) DEFAULT NULL,
  `serial` varchar(255) DEFAULT NULL,
  `ports_count` int(11) DEFAULT NULL,
  `rack` varchar(100) DEFAULT NULL,
  `ur_rack` varchar(100) DEFAULT NULL,
  `ip_address` varchar(100) DEFAULT NULL,
  `snmp_community` varchar(100) DEFAULT NULL,
  `creation_date` date NOT NULL,
  `description` text DEFAULT NULL,
  `ports_data_json` longtext NOT NULL,
  `images_json` text DEFAULT NULL,
  `config_files_json` longtext DEFAULT NULL,
  `diagram_json` longtext DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=334 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
