INSERT INTO `mermaid_flows` VALUES (1,'Flujo 1: Macro del Servicio (Ciclo de Vida y Traspaso de Responsabilidades)','','graph TD\n    %% Estilos Globales\n    classDef preventa fill:#d4edda,stroke:#28a745,stroke-width:2px;\n    classDef implem fill:#cce5ff,stroke:#007bff,stroke-width:2px;\n    classDef servicio fill:#fff3cd,stroke:#ffc107,stroke-width:2px;\n    \n    subgraph AREA_PREVENTA [Área: Preventa]\n        A[Identificación de Oportunidad] --> B[Crea Pre-Cliente / Pre-Contrato]\n        B --> C[Asigna Vendedor y Preventa Especialista]\n        C --> D[Carga Reglas de Negocio e Hitos]\n    end\n    class A,B,C,D preventa;\n\n    D -->|Cierre de Ciclo de Preventa y Contrato| E\n\n    subgraph AREA_IMPLEMENTACION [Área: Implementación - Lidera: Carlos Moreno]\n        E[Recepción de Reglas de Negocio] --> F[Creación de Tareas basadas en Reglas]\n        F --> G[Ejecución de Hitos de Implementación]\n        G --> H[Envío de Correo Journey Experience]\n    end\n    class E,F,G,H implem;\n\n    H -->|Traspaso Formal de Responsabilidad| I\n\n    subgraph AREA_SERVICIOS [Área: Servicios / Soporte - Lidera: Yessenia]\n        I[Líder de Servicios elige Gestor a Cargo] --> J[Asignación a Soporte N1, N2 o N3]\n        J --> K[Operación Regular: Gestión de Tickets en Aranda]\n        K --> L[Mantenimientos Correctivos y Preventivos]\n    end\n    class I,J,K,L servicio;\n\n    L --> M((Fin del Contrato / Renovación))','2026-07-02 15:14:18','2026-07-02 15:15:14'),(2,'Flujo 2: Journey Experience y Calificaciones Bidireccionales2','','graph TB\n    %% Estilos de Diseño Profesional (ITIL Compliant)\n    classDef preventa fill:#E8F5E9,stroke:#2E7D32,stroke-width:2px,color:#1B5E20;\n    classDef ventas fill:#E3F2FD,stroke:#1565C0,stroke-width:2px,color:#0D47A1;\n    classDef implem fill:#EDE7F6,stroke:#4527A0,stroke-width:2px,color:#4A148C;\n    classDef soporte fill:#FFF8E1,stroke:#FF8F00,stroke-width:2px,color:#E65100;\n    classDef critico fill:#FFEBEE,stroke:#C62828,stroke-width:2px,color:#B71C1C;\n    classDef hito fill:#ECEFF1,stroke:#37474F,stroke-width:3px,color:#263238;\n\n    %% ==========================================\n    %% CARRIL 1: PREVENTA (Bloque Superior)\n    %% ==========================================\n    subgraph CARRIL_PREVENTA [DEPARTAMENTO DE PREVENTA]\n        direction LR\n        A([Inicio Oportunidad]) --> B[\"Crear Pre-Cliente /<br>Pre-Contrato\"]\n        B --> C[\"Formalizar Datos y<br>Enviar Propuesta\"]\n        C --> D{\"¿Propuesta<br>Aceptada?\"}\n        \n        %% Bucle de Encuesta de Preventa\n        D -- SÍ --> J_PREV[\"Enviar Encuesta<br>Preventa\"]\n        J_PREV --> K_PREV{\"¿Nota<br>Ok?\"}\n        K_PREV -- SÍ --> FB_PREV[\"Feedback Interno:<br>Tipo de Cliente\"]\n        \n        K_PREV -- NO --> L_PREV[\"Plan Mejora<br>Preventa\"]:::critico\n        L_PREV --> M_PREV[\"Ajustar Propuesta<br>Técnica\"]:::critico\n        M_PREV --> J_PREV\n    end\n    class B,C,D,J_PREV,K_PREV,FB_PREV preventa;\n    D -- NO --> TERM_PREV([Oportunidad Perdida]):::critico\n\n    %% ==========================================\n    %% CARRIL 2: VENTAS (Bloque Intermedio Alto)\n    %% ==========================================\n    subgraph CARRIL_VENTAS [DEPARTAMENTO DE VENTAS]\n        direction LR\n        G[\"Asignar ID Contrato<br>y Cliente\"] --> H[\"Cargar Catálogo<br>de Servicios\"]\n        H --> I[\"Firma de Contrato<br>Sonda / Cliente\"]\n        I --> J_VNT[\"Enviar Encuesta<br>Comercial\"]\n        \n        %% Bucle de Encuesta Comercial\n        J_VNT --> K_VNT{\"¿Nota<br>Ok?\"}\n        K_VNT -- SÍ --> FB_VNT[\"Feedback Interno:<br>Comportamiento\"]\n        \n        K_VNT -- NO --> L_VNT[\"Plan Mejora<br>Comercial\"]:::critico\n        L_VNT --> M_VNT[\"Revisar Acuerdos<br>Contractuales\"]:::critico\n        M_VNT --> N_VNT[\"Aprobación de<br>Nuevo Journey\"]:::critico\n        N_VNT --> J_VNT\n    end\n    class G,H,I,J_VNT,K_VNT,FB_VNT ventas;\n\n    %% ==========================================\n    %% CARRIL 3: IMPLEMENTACIÓN (Bloque Intermedio Bajo)\n    %% ==========================================\n    subgraph CARRIL_IMPLEMENTACION [DEPARTAMENTO DE IMPLEMENTACIÓN - Carlos Moreno]\n        direction LR\n        P[\"Inyectar Tareas según<br>Reglas Preventa\"] --> Q[\"Estandarización y<br>Ejecución Especialistas\"]\n        Q --> R[\"Cierre Técnico con<br>Visto Bueno Cliente\"]\n        R --> S_IMP[\"Enviar Encuesta<br>de Proyecto\"]\n        \n        %% Bucle de Encuesta de Proyecto\n        S_IMP --> T_IMP{\"¿Nota<br>Ok?\"}\n        T_IMP -- SÍ --> FB_IMP[\"Feedback Interno:<br>Madurez Técnica\"]\n        \n        T_IMP -- NO --> L_IMP[\"Plan Mejora<br>Proyecto\"]:::critico\n        L_IMP --> M_IMP[\"Ajustar Entregables<br>y Garantías\"]:::critico\n        M_IMP --> S_IMP\n    end\n    class P,Q,R,S_IMP,T_IMP,FB_IMP implem;\n\n    %% ==========================================\n    %% CARRIL 4: SOPORTE Y SERVICIOS (Bloque Inferior)\n    %% ==========================================\n    subgraph CARRIL_SOPORTE [DEPARTAMENTO DE SERVICIOS / SOPORTE - Yessenia]\n        direction LR\n        V[\"Activar Servicios<br>Operativos Asociados\"] --> W[\"Ventana de Tiempo<br>Soporte / Mtto.\"]\n        W --> X_SOP[\"Enviar Encuesta<br>Periódica Soporte\"]\n        \n        %% Evaluación y Contingencia Interna\n        X_SOP --> Y_SOP{\"¿Nota<br>Ok?\"}\n        Y_SOP -- SÍ --> FB_SOP[\"Feedback Interno:<br>Uso de Canales\"]\n        FB_SOP --> AB{\"¿Fin de<br>Contrato?\"}\n        \n        Y_SOP -- NO --> Z_SOP[\"Plan Mejora<br>Interno Operativo\"]:::critico\n        Z_SOP --> AA_SOP[\"Registrar Constancia<br>en Historial\"]:::critico\n        AA_SOP --> W\n        \n        AB -- NO --> W\n        AB -- SÍ --> AC[\"Cierre Formal y<br>Liquidación Final\"]\n    end\n    class V,W,X_SOP,Y_SOP,FB_SOP,AB,AC soporte;\n\n    %% ==========================================\n    %% ENLACES E INTERCONEXIONES VERTICALES (HANDOVERS)\n    %% ==========================================\n    %% Forzamos que las flechas de handover apunten directo al piso de abajo\n    FB_PREV -->|Handover Comercial| G\n    FB_VNT  -->|Handover Técnico| P\n    FB_IMP  -->|Handover Operativo| V\n    AC      --> FIN_JOURNEY([FIN DEL VIAJE<br>DEL CLIENTE]):::hito','2026-07-02 15:16:23','2026-07-02 15:45:46'),(3,'Flujo 3: Generación de Tickets y Control de Tareas Diarias','','graph TD\n    classDef operacion fill:#e2e3e5,stroke:#383d41,stroke-width:2px;\n    classDef regla fill:#fff3cd,stroke:#ffc107,stroke-width:2px;\n    classDef backend fill:#cce5ff,stroke:#007bff,stroke-width:2px;\n    A[Apertura de Ticket en Aranda / NOVAIOPS]:::operacion --> B[Asignación a Especialista N1, N2 o N3]:::operacion\n    B --> C[Técnico presiona botón PLAY en Ticket]:::operacion\n    \n    C --> D{\"¿Requiere tareas administrativas adicionales?<br><i>(Documentación, revisión proveedores, etc.)</i>\"}:::operacion\n    \n    D -- SÍ --> E[Crear Tarea Hija ligada al Ticket Padre]:::operacion\n    E --> F[Técnico ejecuta actividades de apoyo]:::operacion\n    F --> G[Técnico presiona botón STOP en Ticket]:::operacion\n    \n    D -- NO --> H[Técnico ejecuta el Servicio Principal]:::operacion\n    H --> G\n    \n    G --> I[Cierre del Ticket Técnico]:::operacion\n    \n    subgraph Motor_de_Reglas [Motor de Reglas de Negocio - Parametrizado por Preventa]\n        I --> J[Identificar Horas: Nocturnas, Feriados o Fuera de Horario]:::regla\n        J --> K[Evaluar Umbral Mínimo para Redondeo de Hora Total]:::regla\n        K --> L[Excluir Tiempo de Tareas Hijas del descuento del Cliente]:::regla\n    end\n    L --> M[Cálculo Automático de Horas a Descontar]:::backend\n    M --> N[Descontar horas ejecutadas de la Bolsa de Soporte]:::backend\n    N --> O[Generar Hoja de Servicio Automatizada]:::backend\n    O --> P[Envío de Hoja de Servicio por Correo al Cliente]:::backend\n    \n    P --> Q[Consolidar tiempo en Perfil de Personal]:::backend\n    Q --> R((Validación: Mínimo 1 tarea diaria registrada)):::operacion','2026-07-02 15:18:45','2026-07-02 15:18:45');
/*!40000 ALTER TABLE `mermaid_flows` ENABLE KEYS */;
UNLOCK TABLES;

