DROP TABLE IF EXISTS `novaiops_informacion_reportes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `novaiops_informacion_reportes` (
  `id_internal` int(11) NOT NULL AUTO_INCREMENT,
  `id_tarea` text DEFAULT NULL,
  `ticket_arranda` text DEFAULT NULL,
  `descripcion` text DEFAULT NULL,
  `solicitante` text DEFAULT NULL,
  `cliente` text DEFAULT NULL,
  `contrato` text DEFAULT NULL,
  `version` text DEFAULT NULL,
  `servicio` text DEFAULT NULL,
  `frecuencia` text DEFAULT NULL,
  `fecha` text DEFAULT NULL,
  `hora_inicio_soporte` text DEFAULT NULL,
  `hora_fin_soporte` text DEFAULT NULL,
  `horas_efectivas` text DEFAULT NULL,
  `tiempo_efectivo_estandar_l_v_8_18` text DEFAULT NULL,
  `tiempo_efectivo_nocturno_18_8` text DEFAULT NULL,
  `tiempo_efectivo_fin_de_semana_vie_18_lun_8` text DEFAULT NULL,
  `horas_comerciales` text DEFAULT NULL,
  `upload_id` int(11) DEFAULT 0,
  PRIMARY KEY (`id_internal`)
) ENGINE=InnoDB AUTO_INCREMENT=1989 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

