INSERT INTO `novaiops_informacion_reportes` VALUES (1,'2','Informe - 2','RF-7926587 Mantenimiento de switches','Marcia Contento Tenezaca','UNIVERSIDAD DE LAS AMERICAS','RENOVACIÓN SOPORTE PSS','DCC56','Mantenimiento Preventivo','Anual','6 abr 2026','10:52','12:03','1:10','1:10','','','1:15',7),(2,'2','Informe - 2','RF-7926587 Mantenimiento de switches','Marcia Contento Tenezaca','UNIVERSIDAD DE LAS AMERICAS','RENOVACIÓN SOPORTE PSS','DCC56','Mantenimiento Preventivo','Anual','6 abr 2026','12:55','15:57','3:02','3:02','','','3:15',7),(3,'3','Informe - 3','Elaboración de informe mensual de Seguridad Perimetral // CFN','Santiago Gomez Lagua','CORPORACION FINANCIERA NACIONAL CFN','Servicios gestionados de Seguridad','CYBER0015','Servicio Sonda','5x8','6 abr 2026','11:10','13:00','1:49','1:49','','','2:00',7),(4,'3','Informe - 3','Elaboración de informe mensual de Seguridad Perimetral // CFN','Santiago Gomez Lagua','CORPORACION FINANCIERA NACIONAL CFN','Servicios gestionados de Seguridad','CYBER0015','Servicio Sonda','5x8','6 abr 2026','13:01','15:03','2:02','2:02','','','2:15',7),(5,'3','Informe - 3','Elaboración de informe mensual de Seguridad Perimetral // CFN','Santiago Gomez Lagua','CORPORACION FINANCIERA NACIONAL CFN','Servicios gestionados de Seguridad','CYBER0015','Servicio Sonda','5x8','6 abr 2026','15:03','20:02','4:58','2:56','2:02','','9:00',7),(6,'3','Informe - 3','Elaboración de informe mensual de Seguridad Perimetral // CFN','Santiago Gomez Lagua','CORPORACION FINANCIERA NACIONAL CFN','Servicios gestionados de Seguridad','CYBER0015','Servicio Sonda','5x8','6 abr 2026','20:40','20:41','0:00','','0:00','','2:00',7),(7,'4','RF-7446275','Estimado, Byron_x000D_\n_x000D_\nBuenos Días_x000D_\n_x000D_\nEn seguimiento al servicio ofertado, me permito compartir la actualización de las actividades, conforme a lo revisado con nuestro especialista Santiago Ushiña:_x000D_\n_x000D_\nLunes 6 Abril _x000D_\n_x000D_\nSesión de 09:00 a 10:00_x000D_\n_x000D_\n•	Se verificó el servidor CUCM Subscriber TARUC101 posterior a un reinicio no controlado y un mensaje de alerta sucedido semanas atrás. El servidor no presenta errores o funcionamiento anormal por lo que se desactivo dicha alerta._x000D_\n•	Se recopiló información adicional del servidor necesaria para validaciones con el nuevo servidor de remplazo en la ventana de mantenimiento programada para el día viernes 10 de Abril._x000D_\n_x000D_\nViernes 10 Abril_x000D_\n_x000D_\nVentana Programa _x000D_\n_x000D_\n•	Se validará la presencia de un respaldo reciente que se utilizará el día viernes 10 de Abril._x000D_\n•	La ventana del día viernes 10 de abril se ejecutaría unos minutos antes de las 18:00. _x000D_\n•	Las actividades serán:_x000D_\n_x000D_\no	Verificación de cantidad de teléfonos registrados al servidor subscriber TARUC101 antes de inicio de actividades._x000D_\no	Paso de registro de 6 extensiones (reportadas en la última ocasión con problemas) de la localidad TAR a un servidor subscriber de Quito._x000D_\no	Desconexión del servidor original TARUC101 (sin apagarlo)_x000D_\no	Encendido de la máquina virtual nueva de remplazo desplegada semanas atrás (actualmente desconectada y apagada). _x000D_\no	Instalación de parches adicionales faltantes (\"Ungracefull restart\" y \"Telemetry agent\")._x000D_\no	Restauración desde backup del servidor TARUC101 (nuevo)_x000D_\no	Validación de servicios, replicación de BD y registro de dispositivos._x000D_\n_x000D_\n•	Se solicitó la ayuda de personal en sitio de la localidad TAR para verificación de registro de teléfonos y pruebas desde la red 172.17.0.0 en el horario aproximadamente de 19:30 a 20:00 pm en adelante._x000D_\n•	La ventana se estima que tendrá una duración de tres a cuatro horas.','José Jibaja Robles','ANDES PETROLEUM ECUADOR LTD.','ACTUALIZACIÓN DE LA PLATAFORMA DE COMUNICACIONES UNIFICADAS OC-3107','NA84','Horas de Soporte','Por Contrato','6 abr 2026','11:11','12:11','1:00','1:00','','','1:15',7),(8,'4','RF-7446275','Estimado, Byron_x000D_\n_x000D_\nBuenos Días_x000D_\n_x000D_\nEn seguimiento al servicio ofertado, me permito compartir la actualización de las actividades, conforme a lo revisado con nuestro especialista Santiago Ushiña:_x000D_\n_x000D_\nLunes 6 Abril _x000D_\n_x000D_\nSesión de 09:00 a 10:00_x000D_\n_x000D_\n•	Se verificó el servidor CUCM Subscriber TARUC101 posterior a un reinicio no controlado y un mensaje de alerta sucedido semanas atrás. El servidor no presenta errores o funcionamiento anormal por lo que se desactivo dicha alerta._x000D_\n•	Se recopiló información adicional del servidor necesaria para validaciones con el nuevo servidor de remplazo en la ventana de mantenimiento programada para el día viernes 10 de Abril._x000D_\n_x000D_\nViernes 10 Abril_x000D_\n_x000D_\nVentana Programa _x000D_\n_x000D_\n•	Se validará la presencia de un respaldo reciente que se utilizará el día viernes 10 de Abril._x000D_\n•	La ventana del día viernes 10 de abril se ejecutaría unos minutos antes de las 18:00. _x000D_\n•	Las actividades serán:_x000D_\n_x000D_\no	Verificación de cantidad de teléfonos registrados al servidor subscriber TARUC101 antes de inicio de actividades._x000D_\no	Paso de registro de 6 extensiones (reportadas en la última ocasión con problemas) de la localidad TAR a un servidor subscriber de Quito._x000D_\no	Desconexión del servidor original TARUC101 (sin apagarlo)_x000D_\no	Encendido de la máquina virtual nueva de remplazo desplegada semanas atrás (actualmente desconectada y apagada). _x000D_\no	Instalación de parches adicionales faltantes (\"Ungracefull restart\" y \"Telemetry agent\")._x000D_\no	Restauración desde backup del servidor TARUC101 (nuevo)_x000D_\no	Validación de servicios, replicación de BD y registro de dispositivos._x000D_\n_x000D_\n•	Se solicitó la ayuda de personal en sitio de la localidad TAR para verificación de registro de teléfonos y pruebas desde la red 172.17.0.0 en el horario aproximadamente de 19:30 a 20:00 pm en adelante._x000D_\n•	La ventana se estima que tendrá una duración de tres a cuatro horas.','José Jibaja Robles','ANDES PETROLEUM ECUADOR LTD.','ACTUALIZACIÓN DE LA PLATAFORMA DE COMUNICACIONES UNIFICADAS OC-3107','NA84','Horas de Soporte','Por Contrato','6 abr 2026','12:55','12:55','0:00','0:00','','','1:00',7),(9,'5','Informe - 5','Dayli Redes','José Jibaja Robles','SONDA ECUADOR','Tareas internas de  Sonda ','SONDA0001A','Servicios Internos de Sonda','Bajo demanda','6 abr 2026','12:17','12:48','0:31','0:31','','','1:00',7),(10,'6','Capacitación - 6','Capacitacion interna','Marco Vizcaino Pazmiño','SONDA ECUADOR','Tareas internas de  Sonda ','SONDA0001A','Servicios Internos de Sonda','Bajo demanda','6 abr 2026','12:50','12:52','0:01','0:01','','','1:00',7),(11,'6','Capacitación - 6','Capacitacion interna','Marco Vizcaino Pazmiño','SONDA ECUADOR','Tareas internas de  Sonda ','SONDA0001A','Servicios Internos de Sonda','Bajo demanda','6 abr 2026','12:52','12:52','0:00','0:00','','','1:00',7),(12,'7','Implementación - 7','Proyecto de migración de infraestructura hacia Azure, incluyendo replicación de servidores, validación de recursos, configuración de redes, revisión de ExpressRoute y pruebas de migración. Actualmente se trabaja en la replicación de la última máquina virtual, la cual presenta inconsistencias, por lo que se están realizando validaciones adicionales con el cliente y proveedores para completar la migración.','Cesar Taco Cabrera','OPERADOR NACIONAL DE ELECTRICIDAD - CENACE','PAM','CYBER0018','Servicio Sonda','5x8','','','','','','','','',7),(13,'8','Informe - 8','Elaboración del informe mensual de CFN','Kevin Plazarte Falcon','CORPORACION FINANCIERA NACIONAL CFN','Servicios gestionados de Seguridad','CYBER0015','Servicio Sonda','5x8','6 abr 2026','14:09','22:12','8:02','3:50','4:12','','14:00',7),(14,'9','Sesión - Reunión - 9','Creación Dashboards cortex con la data de logs de los firewalls','Christian Mantilla Yunga','BANCO INTERNACIONAL S.A.','Renovación Palo alto Cortex XRD','CYBER